import { test, expect } from '@playwright/test';

test.describe('Form Submission in Modal Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-modal');
  });

  test('should successfully submit a form from a modal and display success message', async ({ page }) => {
    // Open the modal by clicking the trigger button
    const openButton = page.getByRole('button', { name: /open form/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="form-modal"]');
    await expect(modal).toBeVisible();

    // Fill in form fields using getByLabel
    const nameInput = page.getByLabel(/full name/i);
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel(/email address/i);
    await emailInput.fill('john@example.com');

    const messageInput = page.getByLabel(/message/i);
    await messageInput.fill('This is a test message.');

    // Click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for API response and success message to appear
    const successMessage = page.getByText(/form submitted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify modal is still open and form is cleared
    await expect(modal).toBeVisible();
    await expect(nameInput).toHaveValue('');
    await expect(emailInput).toHaveValue('');
    await expect(messageInput).toHaveValue('');
  });

  test('should display validation errors when submitting an empty form from a modal', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open form/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.locator('[data-testid="form-modal"]');
    await expect(modal).toBeVisible();

    // Attempt to submit form without filling any fields
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify validation error messages appear
    const nameError = page.getByText(/full name is required/i);
    await expect(nameError).toBeVisible();

    const emailError = page.getByText(/email is required/i);
    await expect(emailError).toBeVisible();

    const messageError = page.getByText(/message is required/i);
    await expect(messageError).toBeVisible();

    // Verify success message does not appear
    const successMessage = page.getByText(/form submitted successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify modal is still open
    await expect(modal).toBeVisible();
  });
});
